import{_ as a,o as n,c as t,a4 as i}from"./chunks/framework.B-wJupoK.js";const o="/assets/image-20240601174144308.XsFtZ7I2.png",s="/assets/image-20240601174322991.C0CUcuzy.png",r="/assets/image-20240601174223199.DL0VT6EF.png",l="/assets/image-20240601174647833.BI3Spn0o.png",m="/assets/image-20240601175545211.CouEpoFF.png",c="/assets/image-20240601175701046.BBeBO8Am.png",p="/assets/image-20240606235540615.D1XdNIT_.png",d="/assets/image-20240607000214437.BsYrQzUW.png",g="/assets/image-20240607000307371.BjcWcvqL.png",h="/assets/image-20240607000516199.DD5ixNZI.png",u="/assets/image-20240607001711247.Drar_q0A.png",b="/assets/image-20240607001418717.SbniHXgb.png",_="/assets/image-20240607001512982.9WIjSsql.png",q="/assets/image-20240607001932508.DpNMFT5w.png",k="/assets/image-20240607002916045.C4-4ZHkR.png",f="/assets/image-20240607003105533.OusHLGcP.png",C="/assets/image-20240607003149764.DHZV42SP.png",x="/assets/image-20240607003413990.CAzWrtih.png",P="/assets/image-20240607003713527.B31Eo2VC.png",S="/assets/image-20240607004122978.BELnkYlw.png",E="/assets/image-20240607004008260.B97JsX9e.png",D="/assets/image-20240607004546384.DZNU-jmx.png",T=JSON.parse('{"title":"最新 HUAWEI DevEco Studio 使用技巧","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/鸿蒙编辑器使用技巧/鸿蒙编辑器使用技巧.md","filePath":"鸿蒙开发技巧/鸿蒙编辑器使用技巧/鸿蒙编辑器使用技巧.md","lastUpdated":1758030697000,"__rawMarkdown":"# 最新 HUAWEI DevEco Studio 使用技巧\\n\\n**HUAWEI DevEco Studio** 作为我们 harmonyos 应用的开发工具，有必要好好打磨一下。\\n\\n\\n\\n## Chinese(Simplified) 中文汉化插件\\n\\n![image-20240601174144308](readme.assets/image-20240601174144308.png)\\n\\n---\\n\\n##  GitToolBox 编辑器中显示git历史\\n\\n---\\n\\n![image-20240601174322991](readme.assets/image-20240601174322991.png)\\n\\n\\n\\n![image-20240601174223199](readme.assets/image-20240601174223199.png)\\n\\n\\n\\n## 保存时自动格式化\\n\\n写了一堆代码，当保存时，自动帮你格式化\\n\\n![image-20240601174647833](readme.assets/image-20240601174647833.png)\\n\\n\\n\\n## 切换Ohos视图\\n\\n项目本来的视图 是以实际的文件目录来展示的，可能会比较繁琐和层级过深 如：\\n\\n![image-20240601175545211](readme.assets/image-20240601175545211.png)\\n\\n可以修改为 以项目的角度来划分的视图\\n\\n![image-20240601175701046](readme.assets/image-20240601175701046.png)\\n\\n## 更换快捷键方案\\n\\n**HUAWEI DevEco Studio**  提供了常见的其他编辑器的键盘方案，可以自由选择\\n\\n![image-20240606235540615](readme.assets/image-20240606235540615.png)\\n\\n\\n\\n## 随处搜索\\n\\n> 整个项目搜索，包括文件名称和代码内容\\n\\n`双击 shift`\\n\\n## 转到文件\\n\\n> 快速打开文件\\n\\n`Ctrl + P`\\n\\n![image-20240607000214437](readme.assets/image-20240607000214437.png)\\n\\n## 最近的文件\\n\\n> 快速打开最近操作过的文件\\n\\n`Ctrl+E`\\n\\n![image-20240607000307371](readme.assets/image-20240607000307371.png)\\n\\n## 在文件中查找\\n\\n> 全项目文件中搜索文本内容，全盘搜索某个页面中的关键字很实用\\n\\n`Ctrl+Shift+F`\\n\\n![image-20240607000516199](readme.assets/image-20240607000516199.png)\\n\\n## 在文件中替换\\n\\n> 全盘搜索项目中的文件，并且进行替换    *建议使用编辑器中 **重构**来实现*\\n\\n![image-20240607001711247](readme.assets/image-20240607001711247.png)\\n\\n## 当前文件内搜索\\n\\n> 在当前打开的文件中搜索匹配的字符\\n\\n`Ctrl + F`\\n\\n![image-20240607001418717](readme.assets/image-20240607001418717.png)\\n\\n## 当前文件内搜索替换\\n\\n> 在当前打开的文件中搜索匹配的字符 并且替换\\n\\n`Ctrl+H`\\n\\n![image-20240607001512982](readme.assets/image-20240607001512982.png)\\n\\n## 定位到文件中的某一行和某一列\\n\\n`Ctrl+G`\\n\\n![image-20240607001932508](readme.assets/image-20240607001932508.png)\\n\\n## 切换书签\\n\\n> 在当前文件当前行添加一个书签，后面可以通过快捷键快速定位到当前书签\\n\\n1. 切换书签 *可以有多个书签*  `Ctrl+Shift+1`、`Ctrl+Shift+2`、、、\\n\\n   ![image-20240607002916045](readme.assets/image-20240607002916045.png)\\n\\n2. 定位到书签  `Ctrl+1`、`Ctrl+2`、`Ctrl+3`\\n\\n\\n\\n## 跳到上次编辑的位置\\n\\n`Alt+Q`\\n\\n![image-20240607003105533](readme.assets/image-20240607003105533.png)\\n\\n\\n\\n## 跳到下次编辑的位置\\n\\n`Alt+W`\\n\\n![image-20240607003149764](readme.assets/image-20240607003149764.png)\\n\\n## 将下一次出现项添加到选择\\n\\n> 将当前鼠标选中的内容 继续往下多选,实现批量编辑\\n\\n`Ctrl+D`\\n\\n![image-20240607003413990](readme.assets/image-20240607003413990.png)\\n\\n## 多列选择\\n\\n> 实现纵向多光标\\n\\n`Ctrl+Alt+↑`\\n\\n![image-20240607003713527](readme.assets/image-20240607003713527.png)\\n\\n## 鼠标选中快捷操作\\n\\n1. 鼠标双击 选中当前光标所在单词\\n2. 鼠标三击 选中一行\\n\\n\\n\\n## 扩展选择\\n\\n> 从光标出发，可以拓展选中的范围 \\n\\n`Ctrl+Q`\\n\\n![image-20240607004122978](readme.assets/image-20240607004122978.png)\\n\\n---\\n\\n\\n\\n![image-20240607004008260](readme.assets/image-20240607004008260.png)\\n\\n## 上下两行互换位置\\n\\n`Ctrl+Shift+上箭头/下箭头`\\n\\n## 快速跳到行首/行尾\\n\\n1. 行首 `Home` \\n2. 行尾 `End`\\n\\n\\n\\n## 使用JSDoc风格给函数添加注释\\n\\n当我们调用函数的时候会有更加友好的提示\\n![image-20240607004008260](readme.assets/image-20240607004546384.png)\\n\\n在你想要添加注释的函数上方：\\n\\n1. 输入 `/**`  \\n2. 然后按下回车即可\\n\\n\\n\\n## 结束\\n\\n如果可以帮助到你，欢迎来撩\\n\\n1. 邮箱 `yeah126139163@163.com`\\n2. 微信 `w846903522`\\n3. [掘金](https://juejin.cn/user/4441682708283191)\\n4. [b站](https://link.juejin.cn/?target=https%3A%2F%2Fspace.bilibili.com%2F414874315%3Fspm_id_from%3D333.1007.0.0)\\n5. 公众号 `HarmonyOS 万少`"}'),A={name:"鸿蒙开发技巧/鸿蒙编辑器使用技巧/鸿蒙编辑器使用技巧.md"};function H(F,e,I,B,W,j){return n(),t("div",null,[...e[0]||(e[0]=[i("",85)])])}const U=a(A,[["render",H]]);export{T as __pageData,U as default};
